Reusable API Schema Object: Project

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "example": "prj_99xyz888"
    },
    "name": {
      "type": "string",
      "example": "Frontend Application"
    },
    "framework": {
      "type": "string",
      "example": "nextjs"
    },
    "repository": {
      "type": "string",
      "example": "github.com/organization/repo"
    },
    "status": {
      "type": "string",
      "enum": [
        "building",
        "ready",
        "failed"
      ],
      "example": "ready"
    }
  }
}

